    }()
    case .publishedProducts?: try {
      guard case .publishedProducts(let v)? = self.field else { preconditionFailure() }
      try visitor.visitSingularBoolField(value: v, fieldNumber: 8)
    }()
    case .productTitle?: try {
      guard case .productTitle(let v)? = self.field else { preconditionFailure() }
      try visitor.visitSingularStringField(value: v, fieldNumber: 9)
    }()
    case .publisherName?: try {
      guard case .publisherName(let v)? = self.field else { preconditionFailure() }
      try visitor.visitSingularStringField(value: v, fieldNumber: 10)
    }()
    case .isPublished?: try {
      guard case .isPublished(let v)? = self.field else { preconditionFailure() }
