    }
    try unknownFields.traverse(visitor: &visitor)
  }

  public static func ==(lhs: S12CNTFilter, rhs: S12CNTFilter) -> Bool {
    if lhs.field != rhs.field {return false}
    if lhs.unknownFields != rhs.unknownFields {return false}
    return true
  }
